CustomField.formula:
IF(TEXT(PMC_CPQ_QuoteRecordSubType__c)="International","", IF(
ISPICKVAL( PMC_CPQ_Region__c, 'North America') ,
IF( RecordType.DeveloperName ='PMC_CPQ_International','',
IF(TEXT(PMC_CPQ_QuoteRecordSubType__c)="Industrial","",
IF( or(TEXT(PMC_CPQ_QuoteRecordSubType__c)='Co-Products' ,TEXT(PMC_CPQ_QuoteRecordSubType__c)='Raw Material'),'Co-Product',
TEXT(PMC_CPQ_QuoteRecordSubType__c))
)
) ,
IF( OR(TRIM(RIGHT( TEXT( PMC_CPQ_QuoteRecordSubType__c ),LEN(TEXT( PMC_CPQ_QuoteRecordSubType__c ))-6) )="Potash",
TRIM(RIGHT( TEXT( PMC_CPQ_QuoteRecordSubType__c ),LEN(TEXT( PMC_CPQ_QuoteRecordSubType__c ))-6) )="Paraguay"),"",
if(TEXT(PMC_CPQ_QuoteRecordSubType__c)='B2B_Specialities','Co-Product',TRIM(RIGHT( TEXT( PMC_CPQ_QuoteRecordSubType__c ),LEN(TEXT( PMC_CPQ_QuoteRecordSubType__c ))-6) )))
)
)
